package com.rpb.reservation.workforce;
import com.rpb.reservation.workforce.api.WorkforcePayChangeController;import com.rpb.reservation.workforce.payroll.governance.*;import com.rpb.reservation.workforce.domain.WorkforceException;import com.rpb.reservation.walkin.api.*;
import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.test.web.servlet.MockMvc;import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
class WorkforcePayChangeApiTest {
 CurrentActorProvider actors=mock(CurrentActorProvider.class);PayChangeService requests=mock(PayChangeService.class);PayChangeImpactService impacts=mock(PayChangeImpactService.class);UUID store=UUID.randomUUID(),id=UUID.randomUUID(),company=UUID.randomUUID(),employee=UUID.randomUUID();String base="/api/v1/stores/"+store+"/workforce";MockMvc mvc=MockMvcBuilders.standaloneSetup(new WorkforcePayChangeController(actors,requests,impacts)).build();
 @Test void authenticationNoStoreAndWriteOriginProtectionCoverAllRoutes()throws Exception{when(actors.currentActor()).thenReturn(Optional.empty());for(var path:List.of("/pay-change-requests?companyId="+company,"/pay-change-requests/"+id,"/pay-change-requests/"+id+"/impact?month=2026-11","/pay-change-monthly-baseline?companyId="+company+"&employeeId="+employee+"&month=2026-11"))mvc.perform(get(base+path)).andExpect(status().isUnauthorized()).andExpect(header().string("Cache-Control","private, no-store"));for(var path:List.of("/pay-change-requests/"+id,"/pay-change-requests/"+id+"/actions")){mvc.perform(put(base+path).contentType("application/json").content("{}")).andExpect(status().isForbidden());mvc.perform(put(base+path).header("X-RPB-Workforce","1").header("Sec-Fetch-Site","cross-site").contentType("application/json").content("{}")).andExpect(status().isForbidden());}verifyNoInteractions(requests,impacts);}
 @Test void baselineHasExactIdentityAndConflictRemains409()throws Exception{when(actors.currentActor()).thenReturn(Optional.of(new CurrentActor(UUID.randomUUID(),UUID.randomUUID(),"staff",Set.of(),Set.of(),Set.of())));when(requests.monthlyBaseline(any(),eq(store),eq(company),eq(employee),eq("2026-11"))).thenReturn(com.rpb.reservation.workforce.payroll.PayrollSources.defaultInput(employee));mvc.perform(get(base+"/pay-change-monthly-baseline?companyId="+company+"&employeeId="+employee+"&month=2026-11")).andExpect(status().isOk()).andExpect(jsonPath("$.employeeId").value(employee.toString())).andExpect(jsonPath("$.version").value(0));when(requests.action(any(),any(),any(),any())).thenThrow(WorkforceException.conflict());mvc.perform(put(base+"/pay-change-requests/"+id+"/actions").header("X-RPB-Workforce","1").contentType("application/json").content("{}")).andExpect(status().isConflict()).andExpect(jsonPath("$.code").value("WORKFORCE_CONFLICT"));}
}
